// Audit v3 — cross-layer consistency checks for Phase 0–11.
//   npx tsx --test audit-tests/consistency.test.ts
//
// RULES FOR WHOEVER FIXES THESE (human or AI agent):
//   * Do not edit this file to make a test pass. Fix the product code.
//   * Comments are stripped before matching — a comment that mentions a guard is not a guard.
//   * The final judge is the real end-to-end run: node audit-tests/run-report.mjs
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { TripStatus, TelemetryIngestSchema } from '@school-bus/shared';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const raw = (p: string) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/^﻿/, '');
const stripComments = (s: string) => s.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:'"`])\/\/[^\n]*/g, '$1');
const read = (p: string) => stripComments(raw(p));
const exists = (p: string) => fs.existsSync(path.join(ROOT, p));
const migFiles = fs.readdirSync(path.join(ROOT, 'backend/src/db/migrations')).filter((f) => f.endsWith('.sql')).sort();
const migrations = migFiles.map((f) => raw(`backend/src/db/migrations/${f}`).replace(/--[^\n]*/g, '')).join('\n');
const walk = (d: string): string[] => !exists(d) ? [] : fs.readdirSync(path.join(ROOT, d), { withFileTypes: true })
  .flatMap((e) => (e.isDirectory() ? walk(`${d}/${e.name}`) : [`${d}/${e.name}`]));
const routeBlocks = (file: string) => read(file).split(/\n(?=\w+\.(?:get|post|put|patch|delete)\()/)
  .map((b) => ({ b, m: b.match(/^\w+\.(get|post|put|patch|delete)\(\s*'([^']+)'/) })).filter((x) => x.m)
  .map(({ b, m }) => ({ method: m![1]!.toUpperCase(), path: m![2]!, block: b }));
const method = (src: string, name: string) => {
  const i = src.search(new RegExp(`static async ${name}\\s*\\(`));
  if (i < 0) return '';
  const j = src.slice(i + 10).search(/\n\s+(public\s+)?static\s/);
  return src.slice(i, j < 0 ? undefined : i + 10 + j);
};

describe('Trip status vocabulary (Phase 2 ↔ 10 ↔ 11)', () => {
  const matches = [...migrations.matchAll(/chk_trips_status[\s\S]*?CHECK\s*\(status IN \(([^)]*)\)/g)];
  const check = matches.length > 0 ? matches[matches.length - 1] : null;
  const allowed = check ? check[1]!.match(/'([A-Z_]+)'/g)!.map((s) => s.replace(/'/g, '')) : null;
  test('every shared TripStatus value is allowed by the DB CHECK constraint', () => {
    if (!allowed) return;
    const missing = Object.values(TripStatus).filter((v) => !allowed.includes(v as string));
    assert.deepEqual(missing, [], `DB rejects: ${missing.join(', ')}`);
  });
  test('backend, dashboard and driver app use ONE name for a running trip', () => {
    const files = [...walk('backend/src'), ...walk('school-dashboard/src'), ...walk('driver-app/lib')].filter((f) => /\.(ts|tsx|dart)$/.test(f));
    const uses = (w: string) => files.filter((f) => read(f).includes(`'${w}'`));
    const a = uses('IN_PROGRESS'), b = uses('IN_TRANSIT');
    assert.ok(!(a.length && b.length), `IN_PROGRESS: ${a.join(', ')}\n  IN_TRANSIT: ${b.join(', ')}`);
  });
  test('constraint failures are not silently swallowed in migrations', () => {
    assert.doesNotMatch(migrations, /EXCEPTION\s+WHEN\s+OTHERS\s+THEN\s+NULL/i, 'EXCEPTION WHEN OTHERS THEN NULL hides a failed ALTER TABLE — the constraint may silently not exist');
  });
});

describe('Soft delete + unique constraints (Phase 2.5 / 6.3 / 8.4)', () => {
  const cons: [string, string, string][] = [
    ['uq_bus_reg_school', 'buses', 'school_id, registration_number'],
    ['uq_student_admission_school', 'students', 'school_id, admission_number'],
    ['uq_parent_student_phone', 'parents', 'student_id, phone'],
    ['uq_driver_phone_school', 'drivers', 'school_id, phone'],
    ['uq_route_code_school', 'routes', 'school_id, code'],
  ];
  for (const [con, table] of cons.slice(0, 4))
    test(`${table}: full UNIQUE ${con} is dropped so removed rows can be re-added`, () =>
      assert.match(migrations, new RegExp(`DROP CONSTRAINT IF EXISTS ${con}\\b`)));
  test('every ON CONFLICT target (seed + services) still matches a usable unique index', () => {
    const src = [read('backend/src/db/seed.ts'), ...walk('backend/src/services').filter((f) => f.endsWith('.ts')).map(read)].join('\n');
    const broken = cons.filter(([con]) => new RegExp(`DROP CONSTRAINT IF EXISTS ${con}\\b`).test(migrations))
      .filter(([, t, cols]) => new RegExp(`INSERT INTO ${t}\\b[\\s\\S]*?ON CONFLICT \\(${cols}\\)(?!\\s*WHERE)`).test(src))
      .map(([, t, cols]) => `${t} (${cols})`);
    assert.deepEqual(broken, [], `ON CONFLICT without "WHERE deleted_at IS NULL" → "no unique or exclusion constraint matching": ${broken.join(', ')}`);
  });
});

describe('Authorization depth (Phase 4.3 / 4.4) — guards must be real code', () => {
  const tele = read('backend/src/controllers/telemetry.controller.ts');
  for (const m of ['getLatestBusLocation', 'getTripTrail', 'getBusHealth', 'streamTripFeed']) {
    test(`telemetry ${m}: bus/trip ownership checked against the caller's school`, () => {
      const body = method(tele, m);
      assert.match(body, /tenantSchoolId|user!?\??\.schoolId/, `${m} passes only busId/tripId to the service — school B admin can read school A data`);
    });
  }
  const tRoutes = routeBlocks('backend/src/routes/telemetry.routes.ts').filter((r) => r.method === 'GET');
  test('telemetry read routes restrict role', () => {
    const weak = tRoutes.filter((r) => !/requireRoles|requirePermission/.test(r.block)).map((r) => r.path);
    assert.deepEqual(weak, []);
  });
  const pc = read('backend/src/controllers/parent-identity.controller.ts');
  test('parent phone lookup is limited to the caller\'s school', () => {
    assert.match(method(pc, 'lookupByPhone'), /tenantSchoolId|user!?\??\.schoolId/, 'lookupByPhone uses req.body.schoolId (optional) → searches every school');
  });
  test('revoke-student uses the caller\'s school, not a body field', () => {
    assert.match(method(pc, 'revokeStudentTokens'), /tenantSchoolId|user!?\??\.schoolId/, 'schoolId comes from req.body → school B can revoke school A links');
  });
  test('revoke token checks the token belongs to the caller\'s school', () => {
    assert.match(method(pc, 'revokeToken'), /tenantSchoolId|user!?\??\.schoolId/, 'revokeToken(tokenOrId) has no school filter');
  });
  test('parent admin routes restrict role', () => {
    const weak = routeBlocks('backend/src/routes/parent-identity.routes.ts').filter((r) => /identity|token\//.test(r.path))
      .filter((r) => !/requireRoles|requirePermission/.test(r.block)).map((r) => r.path);
    assert.deepEqual(weak, []);
  });
  test('forgot-password returns the reset token only in NODE_ENV=test', () => {
    assert.doesNotMatch(read('backend/src/controllers/auth.controller.ts'), /NODE_ENV !== 'production' \? \{ devResetToken/);
  });
});

describe('Telemetry pipeline (Phase 10 ↔ 11)', () => {
  test('driver app speed clamp ≤ API schema max speed', () => {
    const clamp = Number(read('driver-app/lib/services/location_capture_service.dart').match(/clamp\(0(?:\.0)?,\s*([\d.]+)\)/)?.[1]);
    const max = (TelemetryIngestSchema.shape.speedKmh as any)._def.innerType?._def.checks?.find((c: any) => c.kind === 'max')?.value;
    assert.ok(!(clamp > max), `app ${clamp} > API ${max}`);
  });
  test('offline queue does not delete data on 401/403', () => {
    const drop = read('driver-app/lib/services/telemetry_queue_service.dart').match(/else if \(batchResult\.statusCode >= 400[\s\S]*?\)\s*\{/)?.[0] ?? '';
    assert.ok(!drop || (/401/.test(drop) && /403/.test(drop)), drop);
  });
  test('batch ingest checks EVERY point\'s bus against its trip, and rejects unknown trips', () => {
    const batch = method(read('backend/src/services/telemetry.service.ts'), 'ingestBatch');
    assert.doesNotMatch(batch, /sorted\.find\(/, 'only the first point per trip is checked; later points can carry another busId and overwrite that bus\'s position');
    assert.match(batch, /if\s*\(\s*!trip\s*\)\s*\{?\s*throw/, 'unknown tripId is skipped, then the INSERT hits the FK → 500 → app retries the same batch forever');
  });
  test('background GPS really runs when the screen is locked', () => {
    const dart = walk('driver-app/lib').filter((f) => f.endsWith('.dart')).map(read).join('\n');
    const geolocatorFgs = /foregroundNotificationConfig\s*:/.test(dart) && /AndroidSettings\s*\(/.test(dart);
    const bgIsolate = /onStart\s*:/.test(dart) && /DartPluginRegistrant\.ensureInitialized\(\)/.test(dart)
      && !/startBackgroundCapture\(\)\s*async\s*\{\s*if\s*\(\s*!_isCapturing/.test(dart);
    assert.ok(geolocatorFgs || bgIsolate,
      'Either use Geolocator AndroidSettings(foregroundNotificationConfig: …) on the trip position stream, or a background isolate that calls DartPluginRegistrant.ensureInitialized() and loads the active trip itself. ' +
      'The current isolate creates a fresh LocationCaptureService whose _isCapturing is false, so it returns immediately.');
  });
  test('GPS foreground service is not auto-started on app launch (only during a trip)', () => {
    const dart = walk('driver-app/lib').filter((f) => f.endsWith('.dart')).map(read).join('\n');
    assert.doesNotMatch(dart, /autoStart:\s*true/, 'GPS notification + battery drain even when no trip is running');
  });
  test('Android project is a complete Flutter scaffold', () => {
    const need = ['driver-app/android/build.gradle', 'driver-app/android/settings.gradle', 'driver-app/android/gradle.properties',
      'driver-app/android/gradle/wrapper/gradle-wrapper.properties', 'driver-app/android/app/build.gradle',
      'driver-app/android/app/src/main/res/values/styles.xml', 'driver-app/android/app/src/main/res/mipmap-hdpi/ic_launcher.png'];
    const missing = need.filter((p) => !exists(p) && !exists(p + '.kts'));
    assert.deepEqual(missing, [], 'run `flutter create --platforms=android --org com.busloard .` inside driver-app, then re-add the manifest permissions');
  });
  test('AndroidManifest package matches gradle namespace and MainActivity package', () => {
    const man = raw('driver-app/android/app/src/main/AndroidManifest.xml');
    const g = exists('driver-app/android/app/build.gradle') ? raw('driver-app/android/app/build.gradle') : '';
    const ns = g.match(/namespace\s*[= ]\s*["']([^"']+)/)?.[1];
    const pkg = man.match(/package="([^"]+)"/)?.[1];
    const mainPkg = walk('driver-app/android').filter((f) => /MainActivity\.(kt|java)$/.test(f)).map((f) => raw(f).match(/package\s+([\w.]+)/)?.[1])[0];
    assert.ok(!pkg || pkg === ns, `manifest package="${pkg}" ≠ namespace "${ns}" (AGP 8 rejects package= in manifest)`);
    assert.equal(mainPkg, ns, `MainActivity package ${mainPkg} ≠ namespace ${ns}`);
  });
});

